/* @autogenerated */
import { Shift, Projected } from '@shared/data/repository/repository.model';
import { ObservedAlertRepository } from 'app/features/observe/observed-alert/repository/observed-alert-repository.service';
import { ListViewCardTemplate, ListViewRowTemplate } from '@shared/toolkit/list-view/list-view.directives';
import {
  ObservedAlertTypes,
  ObservedAlertFilter,
} from 'app/features/observe/observed-alert/model/observed-alert.model';
import { FormControl } from '@angular/forms';
import { contentChild, input, effect, Component, signal } from '@angular/core';
import { DisplayProvider } from '@shared/data/display-provider';

@Component({
  selector: 'observed-alert-view-list',
  templateUrl: './observed-alert-view-list.component.html',
  styleUrls: ['./observed-alert-view-list.component.scss'],
  standalone: false,
})
export class ObservedAlertViewListComponent {
  filters = input<ObservedAlertFilter>();
  actionName = input<string>('observed-alert');
  fixed = input<{ [key: string]: any }>();
  hidden = input<{ [key: string]: any }>();
  /** Estructura de fila o tarjeta que pasa quien usa el listado (`<list-view-row>`/`<list-view-card>` como contenido). */
  rowLayout = contentChild(ListViewRowTemplate);
  cardLayout = contentChild(ListViewCardTemplate);
  search = new FormControl<any>(undefined);
  showSearchLabel = signal('Refresh');
  hideSearchLabel = signal('Refresh');
  readonly list: Shift<Projected<ObservedAlertTypes, 'rule'>[], ObservedAlertFilter>;
  readonly displayer: DisplayProvider<any>;
  refreshDataLabel = signal('Refresh');
  /** Último filtro buscado, sin paginación: lo usa la exportación. */
  query = signal<ObservedAlertFilter>({});

  constructor(repository: ObservedAlertRepository) {
    this.displayer = repository.displayProvider();
    this.list = repository.projections(['rule']);
    effect(() => {
      setTimeout(() => this.makeSearch());
    });
  }
  makeSearch() {
    const result = { limit: 10 } as any;
    const filter = this.search.value;
    const external = this.filters();
    if (external?.search) {
      result.search = external.search;
    }
    if (external?.rule) {
      result.rule = external.rule;
    }
    if (external?.problemKey) {
      result.problemKey = external.problemKey;
    }
    if (external?.status) {
      result.status = external.status;
    }
    if (external?.summary) {
      result.summary = external.summary;
    }
    if (filter?.search) {
      result.search = filter.search;
    }
    if (filter?.rule?.$ref) {
      result.rule = filter.rule.$ref;
    }
    if (filter?.problemKey) {
      result.problemKey = filter.problemKey;
    }
    if (filter?.status) {
      result.status = filter.status;
    }
    if (filter?.summary) {
      result.summary = filter.summary;
    }
    if (filter?.order) {
      result.order = filter.order;
    }
    const { limit, ...query } = result;
    this.query.set(query);
    this.list.fetch(result);
  }

  next() {
    this.list.next();
  }

  reload() {
    this.list.reset();
  }

  prev() {
    console.log('PREV');
  }
}
